SEC = [
 (168, 'అన్వేషిద్దాం – కుటుంబ రకాలు, బంధుత్వ పదాలు', [
  'చుట్టుపక్కల కుటుంబాలు లెక్కించి పట్టిక రాయండి (ఉదా: ఉమ్మడి – 6, చిన్న – 14). ఈ రోజుల్లో చిన్న కుటుంబాలు ఎక్కువ – ఉద్యోగాల కోసం పట్టణాలకు వలస, చిన్న ఇళ్లు, చదువు, స్వతంత్ర జీవనం కారణాలు.',
  'బంధుత్వ పదాలు: అమ్మమ్మ – mother\'s mother; నానమ్మ – father\'s mother; తాత – grandfather; బాబాయి/చిన్నాన్న – father\'s younger brother; పెదనాన్న – father\'s elder brother; పిన్ని – mother\'s younger sister / babai\'s wife; పెద్దమ్మ – mother\'s elder sister; అత్త – father\'s sister / mother-in-law; మామ – mother\'s brother / father-in-law; బావ – sister\'s husband / aunt\'s son; వదిన – elder brother\'s wife.']),
 (170, 'అన్వేషిద్దాం – ఇంట్లో ఎవరు ఏమి చేస్తారు', [
  'జవాబులు మీ ఇంటిని బట్టి రాసి స్నేహితులతో పోల్చండి (ఉదా: సరుకులు – నాన్న/అమ్మ కలిసి; వంట – అమ్మ, నానమ్మ; పెద్దవారు – తాత; ఇల్లు శుభ్రం – అందరూ; గిన్నెలు – అమ్మ, నేను; హోంవర్క్ సహాయం – అక్క). పనులు అందరూ పంచుకుంటే ఎవరిపైనా భారం పడదు.']),
 (172, 'అన్వేషిద్దాం – గీతిక కథ', [
  'కుటుంబ వృక్షం (7 మంది): నానమ్మ → (నాన్న + అమ్మ → గీతిక, తమ్ముడు) మరియు (బాబాయి + పిన్ని → చిన్ని).',
  'బాబాయి ఉద్యోగం పోయి డబ్బు ఇబ్బందిలో ఉన్నారు; పండుగ రోజు ఎవరూ బాధపడకూడదని, కుటుంబం అంటే ఉన్నది పంచుకోవడం, ఒకరికొకరు తోడుండటం అని తల్లిదండ్రులు అందరికీ బట్టలు కొన్నారు.',
  'నేనైతే: గీతికలాగే సంతోషంగా సాధారణ గౌను తీసుకుంటాను; చిన్నితో కలిసి పండుగ చేసుకుంటాను – అందరి సంతోషమే పెద్ద బహుమతి.']),
 (174, 'ఆలోచించండి, అన్వేషిద్దాం – టెన్జింగ్ కథ', [
  'ప్రత్యేక ఖర్చులు ఇద్దరూ కలిసి నిర్ణయిస్తారు – ఇద్దరూ సంపాదిస్తారు, కుటుంబ నిర్ణయాల్లో ఇద్దరికీ సమాన హక్కు, బాధ్యత; కలిసి ఆలోచిస్తే మంచి నిర్ణయం వస్తుంది.',
  'తండ్రి ఇంటిపనుల్లో పాల్గొనడం చాలా మంచిది – పనులు స్త్రీలకు మాత్రమే అనే భావన తప్పు; పంచుకోవడం సమానత్వం.',
  'తాత, నానమ్మ పాత్ర: కథలతో జ్ఞానం, విలువలు నేర్పడం, హోంవర్క్ సహాయం, బస్సు దగ్గరకు తీసుకెళ్ళడం, సమాజ సేవ (విద్యుత్ ఫిర్యాదు, పొరుగువారికి విరాళాలు).',
  'చిన్న కుటుంబాలకు కారణాలు: ఉద్యోగాల కోసం వేరే ఊళ్లకు వలస, చిన్న ఇళ్లు, స్వతంత్రంగా ఉండాలనే కోరిక. ఉమ్మడి కుటుంబం లాభాలు – పని పంచుకోవడం, పిల్లలకు పెద్దల ప్రేమ, కష్టకాలంలో తోడు; నష్టాలు – గోప్యత తక్కువ, అభిప్రాయ భేదాలు. చిన్న కుటుంబం లాభాలు – స్వేచ్ఛ, త్వరిత నిర్ణయాలు; నష్టాలు – పెద్దల తోడు లేకపోవడం, తల్లిదండ్రులపై భారం.']),
 (176, 'సమాజ సహాయ ఉదాహరణలు', [
  'ఉదా: ఊరిలో అగ్నిప్రమాదం జరిగితే అందరూ కలిసి ఇల్లు కట్టడం; చెరువు పూడిక తీయడం (శ్రమదానం); రక్తదాన శిబిరాలు; కోవిడ్ సమయంలో ఆహారం పంచడం; పెళ్ళిళ్ళలో పొరుగువారి సహాయం.']),
 (180, 'కమల్ పర్మార్ కథ – ప్రశ్నలు', [
  'వైఖరి: సమాజం పట్ల బాధ్యత, ఏమీ ఆశించకుండా సేవ చేయడం.',
  'విలువలు: సేవ, దానం, త్యాగం (సొంత సమయం, డబ్బు), కరుణ, విద్య పట్ల గౌరవం.',
  'అవును – ఆ పిల్లలకు పేదరికం వల్ల విద్య, సౌకర్యాలు దక్కలేదు; అది వారి తప్పు కాదు.',
  'సమాజం చేయవలసింది: ఉచిత, నిర్బంధ విద్య (RTE) అమలు, బడి మానేసిన పిల్లలను తిరిగి చేర్చడం, మధ్యాహ్న భోజనం, ఉచిత పుస్తకాలు–యూనిఫారాలు, స్వచ్ఛంద ట్యూషన్లు, బాల కార్మిక వ్యవస్థ నిర్మూలన.']),
 (182, 'మీకు సహాయపడే వారి జాబితా', [
  'ఉపాధ్యాయులు, వైద్యులు, నర్సులు, రైతులు, పాలవారు, కిరాణా దుకాణదారు, బస్సు డ్రైవర్, పారిశుద్ధ్య కార్మికులు, పోస్ట్‌మ్యాన్, విద్యుత్ సిబ్బంది, పోలీసులు, మధ్యాహ్న భోజన వంటవారు, దర్జీ.']),
 (184, 'అన్వేషిద్దాం; ప్రశ్నలు, కృత్యాలు', [
  'నేను భాగమైన సమాజాలు: నా తరగతి, బడి క్రీడా బృందం, సైన్స్/ఎకో క్లబ్, గ్రామ యువజన సంఘం, పాఠశాల బాలల సంఘం – క్లబ్‌కు నాయకుడు, నియమాలు, సమావేశాలు ఉంటాయి.',
  '1) నియమాలు: సమయానికి ఇంటికి రావడం, పెద్దలను గౌరవించడం, ఇంటిపనుల్లో సహాయం, చెత్త డబ్బాలోనే వేయడం, రాత్రి శబ్దం చేయకపోవడం, నీరు వృథా చేయకపోవడం – అందరూ కలిసి శాంతిగా, సురక్షితంగా జీవించడానికి.',
  '2) సామాజిక: యువత స్వతంత్రంగా జీవించాలనుకోవడం, గోప్యత కోరిక. ఆర్థిక: ఉద్యోగాలు, వ్యాపారం కోసం పట్టణాలకు వలస; వ్యవసాయ ఆదాయం తగ్గడం; సొంత సంపాదన. విద్య: ఉన్నత చదువులు, ఉద్యోగాల కోసం దూర ప్రాంతాలకు వెళ్ళడం, ఆధునిక ఆలోచనలు → చిన్న కుటుంబాలు పెరుగుతున్నాయి.',
  '3) అవును, కొన్ని నియమాలు అన్యాయంగా ఉండవచ్చు – ఉదా: ఇంటిపనులన్నీ ఆడపిల్లలకే, ఆడపిల్లల చదువు ఆపడం, కొందరిని ఉమ్మడి బావి/గుడికి రానివ్వకపోవడం. నియమాలు అందరికీ సమానంగా, గౌరవంగా ఉండాలి.',
  '4) ఉదా: వరదల్లో ఆహారం, ఆశ్రయం; ఊరి బడికి దాతల సహాయం; అనారోగ్యంతో ఉన్న వృద్ధులకు పొరుగువారి సహాయం; పంట కోతలో అందరూ కలిసి పనిచేయడం – బొమ్మ గీయండి లేదా రాయండి.']),
]
